// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy, initialize, and add 10 node delegators
        c.initialize(address(0xdead));
        address[] memory ndcs = new address[](10);
        for (uint i = 0; i < 10; i++) {
            ndcs[i] = address(uint160(0x1000 + i));
        }
        // In the reference, paused() returns false, so addNodeDelegatorContractToQueue succeeds.
        // In the buggy version, paused() returns true, causing the whenNotPaused modifier to revert.
        c.addNodeDelegatorContractToQueue(ndcs);
        // Verify: after adding 10, the queue length should be 10
        assertTrue(c.getNodeDelegatorQueue().length == 10);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract
        c.initialize(address(this));

        // Pause the contract
        (bool pauseOk, ) = address(c).call(abi.encodeWithSignature("pause()"));

        // Record what addNodeDelegatorContractToQueue returns
        bool callReverted;
        address[] memory delegators = new address[](1);
        delegators[0] = address(0x1);
        try c.addNodeDelegatorContractToQueue(delegators) {
            callReverted = false;
        } catch {
            callReverted = true;
        }

        // The reference (paused) reverts (true), the buggy (unpaused) succeeds (false)
        // Here we assert the reference behavior: it reverts when paused
        assertTrue(callReverted);
    }
}

