pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: initialize the contract
        address lrtConfigAddr = address(0x1234);
        c.initialize(lrtConfigAddr);

        // Pause the contract
        c.pause();

        // Now attempt to add a node delegator; reference reverts, buggy does not
        bool ok;
        address[] memory nds = new address[](1);
        nds[0] = address(0xaAaAaAaaAaAaAaaAaAaAaaAaaaAaAaAaaAaaAa);
        try c.addNodeDelegatorContractToQueue(nds) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: paused() returns true, so call reverts => ok=false
        // Buggy: paused() returns false, so call succeeds => ok=true
        assertTrue(ok == false, "addNodeDelegatorContractToQueue should revert when paused");
    }
}

