pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Add 11 distinct non-zero addresses to nodeDelegatorQueue
        address[11] memory addrs = [
            address(0x1), address(0x2), address(0x3), address(0x4), address(0x5),
            address(0x6), address(0x7), address(0x8), address(0x9), address(0xA),
            address(0xB)
        ];

        // The call to addNodeDelegatorContractToQueue with 11 addresses should revert on P (max=10) and succeed on M (max=0, bug)
        // We detect this by subsequently calling updateMaxNodeDelegatorCount(1)
        // On P: after revert, maxNodeDelegatorCount is still 10 -> updateMaxNodeDelegatorCount(1) succeeds
        // On M: call succeeds, maxNodeDelegatorCount becomes 0 -> updateMaxNodeDelegatorCount(1) reverts because queue already has 11 addresses > 1

        // First, attempt to add 11 addresses; ignore revert
        try c.addNodeDelegatorContractToQueue(addrs) {
            // succeeded (buggy M)
        } catch {
            // reverted (correct P)
        }

        // Now try to set maxNodeDelegatorCount to 1
        // On P: maxNodeDelegatorCount stays 10 (since addNodeDelegatorContractToQueue reverted), setting to 1 should succeed
        // On M: maxNodeDelegatorCount is 0 (bug), but queue has 11 elements; setting to 1 triggers revert because nodeDelegatorQueue.length (11) > 1
        bool ok;
        address[1] memory oneAddr;
        oneAddr[0] = address(0x1);
        try c.addNodeDelegatorContractToQueue(oneAddr) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference P: addNodeDelegatorContractToQueue with 1 address while queue has 0 (since previous revert) -> succeeds
        // Mutant M: addNodeDelegatorContractToQueue with 1 address while queue has 11 (since previous call succeeded) -> reverts (maxNodeDelegatorCount=0 < 11+1)
        // So on P ok=true, on M ok=false
        assertTrue(ok);
    }
}

